package lab5rmi.client;

import lab5rmi.api.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.rmi.registry.LocateRegistry;
import java.util.UUID;

/** Lightweight desktop dashboard for the replicated RMI record service. */
public final class RecordDashboard extends JFrame {
  private final RecordService service; private final DefaultTableModel model = new DefaultTableModel(new Object[]{"ID","Value","Version","State"},0) { @Override public boolean isCellEditable(int row,int column){return false;} };
  private final JTable table = new JTable(model); private final JTextField id = new JTextField(), value = new JTextField(); private final JLabel status = new JLabel("Connecting…");
  private final JLabel operationStatus = new JLabel("Choose a record ID and value, then create or update a record.");
  private RecordDashboard(RecordService s) { service=s; setTitle("Replicated RMI • Record Dashboard"); setSize(900,570); setLocationByPlatform(true); setDefaultCloseOperation(EXIT_ON_CLOSE);
    getContentPane().setBackground(new Color(245,247,251));
    JPanel top=new JPanel(new BorderLayout(14,0)); top.setOpaque(false); top.setBorder(BorderFactory.createEmptyBorder(18,20,12,20)); JLabel brand=new JLabel("Record Dashboard"); brand.setForeground(new Color(24,52,84)); brand.setFont(new Font("Segoe UI",Font.BOLD,21)); top.add(brand,BorderLayout.WEST); status.setFont(new Font("Segoe UI",Font.PLAIN,12)); status.setForeground(new Color(45,106,93)); status.setOpaque(true); status.setBackground(new Color(225,247,239)); status.setBorder(BorderFactory.createEmptyBorder(8,12,8,12)); top.add(status,BorderLayout.EAST);
    JPanel form=new JPanel(new BorderLayout(10,10)); JPanel fields=new JPanel(new GridLayout(2,2,10,8)); fields.setOpaque(false); form.setOpaque(true); form.setBackground(Color.WHITE); form.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(220,227,237)),BorderFactory.createCompoundBorder(BorderFactory.createEmptyBorder(10,12,10,12),BorderFactory.createTitledBorder("Record mutation")))); fields.add(label("ID")); fields.add(label("Value")); id.setFont(new Font("Segoe UI",Font.PLAIN,13)); value.setFont(new Font("Segoe UI",Font.PLAIN,13)); id.setBorder(fieldBorder()); value.setBorder(fieldBorder()); fields.add(id); fields.add(value); form.add(fields,BorderLayout.CENTER); JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0)); buttons.setOpaque(false); JButton create=new JButton("Create"), update=new JButton("Update"), del=new JButton("Delete"), refresh=new JButton("Refresh"); for(JButton button:new JButton[]{create,update,del,refresh})styleButton(button); buttons.add(create);buttons.add(update);buttons.add(del);buttons.add(refresh); form.add(buttons,BorderLayout.SOUTH);
    create.addActionListener(e->mutate("create")); update.addActionListener(e->mutate("update")); del.addActionListener(e->mutate("delete")); refresh.addActionListener(e->load());
    add(top,BorderLayout.NORTH); JPanel content=new JPanel(new BorderLayout(10,10)); content.setOpaque(false); content.setBorder(BorderFactory.createEmptyBorder(0,20,20,20)); content.add(form,BorderLayout.NORTH); JScrollPane tableScroll=new JScrollPane(table); tableScroll.setBorder(BorderFactory.createLineBorder(new Color(220,227,237))); content.add(tableScroll,BorderLayout.CENTER); operationStatus.setFont(new Font("Segoe UI",Font.PLAIN,12)); operationStatus.setForeground(new Color(92,108,128)); content.add(operationStatus,BorderLayout.SOUTH); add(content,BorderLayout.CENTER); table.getColumnModel().getColumn(0).setPreferredWidth(170); table.getColumnModel().getColumn(1).setPreferredWidth(420); table.getColumnModel().getColumn(2).setPreferredWidth(90); table.getColumnModel().getColumn(3).setPreferredWidth(120); table.setFont(new Font("Segoe UI",Font.PLAIN,13)); table.setRowHeight(30); table.setFillsViewportHeight(true); table.setShowGrid(false); table.setSelectionBackground(new Color(222,235,252)); table.setSelectionForeground(new Color(24,52,84)); table.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12)); table.getTableHeader().setBackground(new Color(239,244,250)); load(); }
  private static JLabel label(String text){JLabel l=new JLabel(text);l.setFont(new Font("Segoe UI",Font.BOLD,12));l.setForeground(new Color(92,108,128));return l;}
  private static javax.swing.border.Border fieldBorder(){return BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(211,220,232)),BorderFactory.createEmptyBorder(7,9,7,9));}
  private static void styleButton(JButton b){b.setFont(new Font("Segoe UI",Font.BOLD,12));b.setFocusPainted(false);b.setBorder(BorderFactory.createEmptyBorder(8,13,8,13));b.setBackground(new Color(232,240,254));b.setForeground(new Color(31,75,130));}
  private void mutate(String op){ try { MutationResult r= op.equals("create")?service.create(UUID.randomUUID().toString(),id.getText(),value.getText()):op.equals("update")?service.update(UUID.randomUUID().toString(),id.getText(),value.getText()):service.delete(UUID.randomUUID().toString(),id.getText()); operationStatus.setText(r.message()); operationStatus.setForeground(r.success()?new Color(45,106,93):new Color(175,45,45)); load(); } catch(Exception e){ operationStatus.setText("Error: "+e.getMessage()); operationStatus.setForeground(new Color(175,45,45)); } }
  private void load(){ try { NodeInfo n=service.info(); status.setText("Node "+n.nodeId()+ (n.primary()?" • PRIMARY":" • REPLICA")+" • pending "+service.pendingReplication()); model.setRowCount(0); for(RecordData r:service.list()) model.addRow(new Object[]{r.id(),r.value(),r.version(),r.deleted()?"Deleted":"Active"}); } catch(Exception e){status.setText("Disconnected: "+e.getMessage());} }
  public static void main(String[] a) throws Exception { String host=a.length>0?a[0]:"127.0.0.1"; int port=a.length>1?Integer.parseInt(a[1]):1099; RecordService s=(RecordService)LocateRegistry.getRegistry(host,port).lookup("RecordService"); SwingUtilities.invokeLater(()->new RecordDashboard(s).setVisible(true)); }
}
